class Solution {
public:
    std::string encode(int num) {
        if (num == 0) return "";
        num += 1;
        std::string res = "";
        while (num > 1) {
            res += (num & 1 ? '1' : '0');
            num >>= 1;
        }
        std::reverse(res.begin(), res.end());
        return res;
    }
};

class Solution {
    public String encode(int num) {
        if (num == 0) return "";
        return Integer.toBinaryString(num + 1).substring(1);
    }
}

var encode = function(num) {
    if (num === 0) return '';
    return (num + 1).toString(2).slice(1);
};
